def transform(grid):
    # Extract the 3x3 pattern with the most distinct nonzero colors: the mixed target.
    from collections import Counter
    comps=[]
    seen=set()
    h,w=len(grid),len(grid[0])
    for r in range(h):
        for c in range(w):
            if grid[r][c] and (r,c) not in seen:
                color=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); cells=[]
                while stack:
                    x,y=stack.pop(); cells.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(x+dx,y+dy)
                        if 0<=q[0]<h and 0<=q[1]<w and q not in seen and grid[q[0]][q[1]]==color:
                            seen.add(q); stack.append(q)
                comps.append((color,cells))
    # Objects are the bounding 3x3 nonzero blocks, each isolated by zero margins.
    blocks=[]
    for r in range(h-2):
      for c in range(w-2):
        vals=[grid[x][y] for x in range(r,r+3) for y in range(c,c+3)]
        if any(vals) and all(grid[x][y]==0 for x in range(r,r+3) for y in range(c,c+3) if vals[(x-r)*3+y-c]==0):
            # candidate only if nonzero cells lie wholly here; dedupe later
            pass
    # Locate occupied bounding boxes via connected components of all nonzero cells, merging adjacent colors.
    points={(r,c) for r in range(h) for c in range(w) if grid[r][c]}
    objs=[]
    while points:
      p=points.pop(); stack=[p]; cells=[p]
      while stack:
        x,y=stack.pop()
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
          q=(x+dx,y+dy)
          if q in points: points.remove(q); stack.append(q); cells.append(q)
      r0=min(x for x,y in cells); r1=max(x for x,y in cells); c0=min(y for x,y in cells); c1=max(y for x,y in cells)
      if r1-r0==2 and c1-c0==2:
        objs.append([[grid[x][y] for y in range(c0,c1+1)] for x in range(r0,r1+1)])
    return max(objs,key=lambda a:len(set(sum(a,[]))))
